def merge_and_standardize(rows1, rows2):
    # Collect each table's feature columns (preserve first-seen order, skip duplicates)
    cols1, cols2 = [], []
    for r in rows1:
        for k in r:
            if k != 'id' and k not in cols1:
                cols1.append(k)
    for r in rows2:
        for k in r:
            if k != 'id' and k not in cols2:
                cols2.append(k)

    # Compute mean and population std dev for each feature column of table 1,
    # ignoring missing (None) values
    stats = []
    for c in cols1:
        vals = [r[c] for r in rows1 if r.get(c) is not None]
        n = len(vals)
        if n == 0:
            mean, sd = 0.0, 0.0
        else:
            mean = sum(vals) / n
            sd = (sum((v - mean) ** 2 for v in vals) / n) ** 0.5
        stats.append((c, mean, sd))

    # Build standardized copies of table 1's rows
    std_rows1 = []
    for r in rows1:
        new_row = {'id': r['id']}
        for c, mean, sd in stats:
            v = r.get(c)
            if v is None:
                new_row[c] = None
            elif sd == 0:            # constant column -> all zeros
                new_row[c] = 0.0
            else:
                new_row[c] = (v - mean) / sd
        std_rows1.append(new_row)

    # Outer join on 'id'
    by_id1 = {r['id']: r for r in std_rows1}
    by_id2 = {r['id']: r for r in rows2}

    result = []
    for i in sorted(set(by_id1) | set(by_id2)):
        r1 = by_id1.get(i, {})
        r2 = by_id2.get(i, {})
        row = {'id': i}
        for c in cols1:
            row[c] = r1.get(c)   # None if id not present or value missing
        for c in cols2:
            row[c] = r2.get(c)
        result.append(row)

    return result
```

**Example checks:**

```python
rows1 = [{'id': 1, 'a': 1.0}, {'id': 2, 'a': 3.0}]
rows2 = [{'id': 2, 'b': 5.0}, {'id': 3, 'b': 7.0}]
print(merge_and_standardize(rows1, rows2))
# [{'id': 1, 'a': -1.0, 'b': None}, {'id': 2, 'a': 1.0, 'b': 5.0}, {'id': 3, 'a': None, 'b': 7.0}]

# Constant column becomes 0
print(merge_and_standardize([{'id': 1, 'a': 5.0}, {'id': 2, 'a': 5.0}], []))
# [{'id': 1, 'a': 0.0}, {'id': 2, 'a': 0.0}]
```

**How it works:**
- Feature columns of table 1 are standardized with `(x - mean) / pstdev`, where mean and standard deviation are computed over the non-`None` values only (population std, dividing by *n*).
- A column with zero standard deviation (constant) is mapped to `0.0` so we never divide by zero.
- Rows are outer-joined on `'id'`: every id from either table appears, and missing cells (either a missing id or a missing value within a present row) are filled with `None`.
- Table 2's values pass through untouched, and the result is sorted by `'id'`.

