import csv
import io


def fill_missing_with_column_mean(csv_text):
    if csv_text is None or csv_text.strip() == '':
        return {}

    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        return {}

    header = rows[0]
    data = rows[1:]

    # Collect values per column, tracking empties.
    columns = {name: [] for name in header}
    for row in data:
        for i, name in enumerate(header):
            cell = row[i].strip() if i < len(row) else ''
            columns[name].append(cell)

    def is_number(s):
        try:
            float(s)
            return True
        except ValueError:
            return False

    result = {}
    for name in header:
        cells = columns[name]
        present = [c for c in cells if c != '']

        # Decide if the column is numeric: it must have at least one present
        # value and every present value must parse as a float.
        numeric = len(present) > 0 and all(is_number(c) for c in present)

        if numeric:
            values = [float(c) for c in present]
            mean = sum(values) / len(values)
            result[name] = [
                float(c) if c != '' else mean for c in cells
            ]
        else:
            result[name] = [c if c != '' else None for c in cells]

    return result
```

How it works:

- **Empty input**: an empty string (or whitespace only) returns `{}`.
- **Parsing**: the `csv` module handles quoting, commas inside fields, and rows with missing trailing cells (short rows are padded with empty strings).
- **Column classification**: a column is numeric only if it has at least one present value *and* all present values parse as floats. Otherwise it's treated as a string column.
- **Numeric columns**: present values become floats; empty cells are filled with the mean of the present values.
- **String columns**: values stay as strings; empty cells become `None`. A column with no values at all (all empty) is a string column by definition, so it becomes all `None`.

Example:

```python
>>> fill_missing_with_column_mean('name,age\nAnn,30\nBob,\nCid,40\n')
{'name': ['Ann', 'Bob', 'Cid'], 'age': [30.0, 35.0, 40.0]}
```

