import calendar
import re
from datetime import date, datetime, timedelta

_WEEKDAYS = {'MON': 0, 'TUE': 1, 'WED': 2, 'THU': 3, 'FRI': 4, 'SAT': 5, 'SUN': 6}


def _parse_freq(freq):
    """Validate freq and return a pattern spec tuple. Raise ValueError if invalid."""
    if not isinstance(freq, str):
        raise ValueError(f"Invalid frequency: {freq!r}")
    value = freq.strip()
    if value.lower() == 'month-end':
        return ('month-end',)
    if value.lower() == 'quarter-end':
        return ('quarter-end',)
    m = re.fullmatch(r'([1-4])-([A-Za-z]{3})', value)
    if m and m.group(2).upper() in _WEEKDAYS:
        week = int(m.group(1))
        return ('nth-weekday', week, _WEEKDAYS[m.group(2).upper()])
    raise ValueError(f"Invalid frequency: {freq!r}")


def _next_match(d, spec):
    """Return the earliest date >= d that matches the pattern spec."""
    kind = spec[0]
    if kind == 'month-end':
        return date(d.year, d.month, calendar.monthrange(d.year, d.month)[1])
    if kind == 'quarter-end':
        for month in (3, 6, 9, 12):
            end = date(d.year, month, calendar.monthrange(d.year, month)[1])
            if end >= d:
                return end
        return date(d.year + 1, 3, 31)
    _, week, weekday = spec
    year, month, min_day = d.year, d.month, d.day
    while True:
        first_weekday = date(year, month, 1).weekday()
        day = 1 + (weekday - first_weekday) % 7 + 7 * (week - 1)
        # week 1-4 means day <= 28, so it always falls inside the month
        if day >= min_day:
            return date(year, month, day)
        month += 1
        if month == 13:
            year, month = year + 1, 1
        min_day = 1


def forecast_schedule(start_date, freq, sales):
    """
    Pair each sales figure with the next scheduled date on or after start_date.

    freq: 'month-end', 'quarter-end', or 'N-WKD' (N in 1..4, WKD in MON..SUN).
    Returns a list of ('YYYY-MM-DD', sales) tuples.
    Raises ValueError for an invalid start date (or invalid freq).
    """
    # Strict 'YYYY-MM-DD' check plus real-calendar check (rejects e.g. 2021-02-30)
    if not isinstance(start_date, str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}', start_date):
        raise ValueError(f"Invalid start date: {start_date!r}")
    try:
        current = datetime.strptime(start_date, '%Y-%m-%d').date()
    except ValueError:
        raise ValueError(f"Invalid start date: {start_date!r}") from None

    spec = _parse_freq(freq)

    schedule = []
    for figure in sales:
        current = _next_match(current, spec)
        schedule.append((current.isoformat(), figure))
        current += timedelta(days=1)  # next match must be strictly after this one
    return schedule
```

**How it works**

- The start date is validated with a strict `YYYY-MM-DD` pattern check and then `strptime`, so impossible dates like `'2021-02-30'` or malformed inputs raise `ValueError`.
- `freq` is parsed into a spec: keyword patterns (`month-end`, `quarter-end`) or an `N-WKD` pattern with week 1–4 and weekday MON–SUN.
- `_next_match` computes the earliest matching date **on or after** a given day in O(1) per step (no day-by-day scanning):
  - *month-end*: last day of the current month via `calendar.monthrange`.
  - *quarter-end*: the first of Mar/Jun/Sep/Dec month-ends not before the current day.
  - *N-WKD*: computed directly from the weekday of the 1st of the month — the N-th occurrence is `1 + (weekday - first_weekday) % 7 + 7*(N-1)`; if that day has already passed, roll to the next month.
- After emitting a date, the cursor advances one day so the next figure gets the *next* match.

**Examples**

```python
print(forecast_schedule('2021-01-01', '2-FRI', [272, 147, 217]))
# [('2021-01-08', 272), ('2021-02-12', 147), ('2021-03-12', 217)]

print(forecast_schedule('2021-02-14', 'month-end', [100, 200]))
# [('2021-02-28', 100), ('2021-03-31', 200)]

print(forecast_schedule('2021-03-31', 'quarter-end', [10, 20, 30]))
# [('2021-03-31', 10), ('2021-06-30', 20), ('2021-09-30', 30)]

forecast_schedule('2021-02-30', 'month-end', [5])   # ValueError
forecast_schedule('2021-01-01', '5-FRI', [5])       # ValueError (week must be 1..4)
```

