def column_covariance(columns):
    """
    Compute the sample covariance matrix of a table.

    The table is given as a dict mapping column names to equal-length
    lists of numbers. The result is a nested dict where result[a][b]
    is the sample covariance (normalised by n - 1) between columns a and b.

    Raises:
        ValueError: if the table has no columns or no rows.
        TypeError:   if any column contains a non-numeric value.
    """
    # --- validation ---------------------------------------------------
    if not columns:
        raise ValueError("table has no columns")

    # Every column must be a non-empty sequence of numbers
    for name, values in columns.items():
        if not isinstance(values, (list, tuple)):
            raise TypeError(f"column {name!r} is not a list of numbers")
        if len(values) == 0:
            raise ValueError("table has no rows")
        for v in values:
            if not isinstance(v, (int, float)):
                raise TypeError(f"column {name!r} contains a non-numeric value: {v!r}")

    # All columns must have the same length
    lengths = {len(values) for values in columns.values()}
    if len(lengths) != 1:
        raise ValueError("columns have different lengths")
    n = lengths.pop()

    if n < 2:
        raise ValueError("covariance requires at least two rows")

    # --- computation ---------------------------------------------------
    means = {
        name: sum(values) / n
        for name, values in columns.items()
    }

    result = {}
    for a, col_a in columns.items():
        row = {}
        mean_a = means[a]
        for b, col_b in columns.items():
            mean_b = means[b]
            cov = sum(
                (col_a[i] - mean_a) * (col_b[i] - mean_b)
                for i in range(n)
            ) / (n - 1)
            row[b] = cov
        result[a] = row

    return result
```

Example usage:

```python
>>> column_covariance({'x': [1, 2, 4], 'y': [3, 1, 2]})
{'x': {'x': 2.3333333333333335, 'y': -0.5}, 'y': {'x': -0.5, 'y': 1.0}}
```

**How it works:**

1. **Validation** — an empty dict or any empty column raises `ValueError`; any non-`int`/`float` entry raises `TypeError`. Mismatched column lengths and tables with fewer than two rows also raise `ValueError` (since `n - 1` must be positive).

2. **Means** — the sample mean of each column is computed once.

3. **Covariance** — for each pair of columns `(a, b)`, the sample covariance is computed as
   `Σᵢ (aᵢ − ā)(bᵢ − b̄) / (n − 1)`,
   which correctly yields the symmetric matrix shown in the example (e.g., `cov(x, x) = ((1−7/3)² + (2−7/3)² + (4−7/3)²)/2 = 2.333...`).

```python
import json
import math


def _is_number(value):
    # bool is a subclass of int in Python, so exclude it explicitly
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _pearson(x, y):
    """Pearson correlation coefficient between two equal-length numeric lists."""
    n = len(x)
    mean_x = sum(x) / n
    mean_y = sum(y) / n
    dx = [xi - mean_x for xi in x]
    dy = [yi - mean_y for yi in y]

    numerator = sum(a * b for a, b in zip(dx, dy))
    denom_x = math.sqrt(sum(a * a for a in dx))
    denom_y = sum(b * b for b in dy)

    if denom_x == 0 or denom_y == 0:
        return None  # correlation undefined (zero variance)

    return numerator / (denom_x * denom_y)


def numeric_correlation_from_json(json_text):
    # Parse the JSON; invalid JSON -> ValueError
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, dict) or not data:
        raise ValueError("Data is empty or not a JSON object of columns.")

    # Collect numeric columns and validate shape
    numeric_cols = {}
    expected_len = None
    for name, values in data.items():
        if not isinstance(values, list) or not values:
            raise ValueError(f"Column '{name}' is not a non-empty list.")
        if expected_len is None:
            expected_len = len(values)
        elif len(values) != expected_len:
            raise ValueError("All columns must have the same length.")
        if all(_is_number(v) for v in values):
            numeric_cols[name] = values

    if not numeric_cols:
        raise ValueError("No numeric columns found.")

    names = list(numeric_cols)
    result = {name: {} for name in names}

    for col1 in names:
        for col2 in names:
            if col1 == col2:
                result[col1][col2] = 1.0
            else:
                r = _pearson(numeric_cols[col1], numeric_cols[col2])
                # Undefined correlation (zero-variance column) -> 0.0
                result[col1][col2] = 0.0 if r is None else r

    return result
```

